---@param btnTF_ table | nil
---@param uiKey_ string  @ Live3D_UIKey
---@param parentEnv_ table | nil
---@param setShowCB_ function | nil     @ func( bool isShow )
---@param setGrayCB_ function | nil     @ func( bool isGray )
---@param btnClickCB_ function | nil    @ func()
function IdolLive3D_UIBasicNode:__init( btnTF_, uiKey_, parentEnv_, setShowCB_, setGrayCB_, btnClickCB_ )

    self.btnTF = btnTF_ -- maybe nil
    self.uiKey = uiKey_ -- Live3D_UIKey
    self.parentEnv = parentEnv_ -- maybe nil
    ---
    self.baseSetShowFunc = setShowCB_ -- maybe nil
    self.baseSetGrayFunc = setGrayCB_ -- maybe nil
    self.baseClickBtnFunc = btnClickCB_ -- maybe nil
    ---
    self.isShow = false
    self.isGray = true
    self.isCustomShow = true -- 用户客制: isShow  额外的一道flag
    self.isCustomGray = false -- 用户客制: isGray 额外的一道flag
    self.customClickFunc = nil -- 定制脚本: 按下按钮后的功能
    --- 
    self:SetShow(self.isShow)
    self:SetGray(self.isGray)
    ---
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        --[IdolLive3D_States.EventChangeUIPosStageJumpBtnImg] = Bind(self, self.SwitchImg),

        -- 允许 客制代码 手动隐藏 本按钮:
        [IdolLive3D_States.EventSetUICustomShow] = function( uiKey_, isShow_, fadeTime_, isEffectImmediately_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            isShow_ = (isShow_==true)
            self.isCustomShow = isShow_
            if isEffectImmediately_ == true then 
                self:SetShow(isShow_)
            end
        end,

        -- 允许 客制代码 手动置灰 本按钮:
        [IdolLive3D_States.EventSetUICustomGray] = function( uiKey_, isGray_, isEffectImmediately_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            isGray_ = (isGray_==true)
            self.isCustomGray = isGray_
            if isEffectImmediately_ == true then 
                self:SetGray(isGray_)
            end
        end,

        -- 外部指定按钮功能, 可写入 nil 来释放;
        [IdolLive3D_States.EventSetUIBtnCustomClickFunc] = function( uiKey_, clickFunc_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            self.customClickFunc = clickFunc_
        end,
    })

    ---
    if isNotNull(self.btnTF) then
        SetButtonAction(self.btnTF, function() 
            --printError("click -1-")
            local parentActive = true
            if isNotNull(self.parentEnv) and type(self.parentEnv.IsActive) == "function" then 
                parentActive = self.parentEnv:IsActive()
            end
            ---
            --printError("click -B- parentActive = " .. tostring(parentActive) .."; isShow = " .. tostring(self.isShow) .. "; isGray = " .. tostring(self.isGray))
            if parentActive and self.isShow == true and self.isGray == false then 
                --printError("click -2-")
                if isNotNull(self.customClickFunc) and type(self.customClickFunc) == "function" then
                    --printError("click -3-")
                    -- 客制按钮功能:
                    self.customClickFunc(self)
                else
                    --printError("click -4-")
                    -- 默认按钮功能:
                    --Events.Broadcast(IdolLive3D_States.EventStageJumpByKey, self.uiKey)
                    if type(self.baseClickBtnFunc) == "function" then 
                        self.baseClickBtnFunc()
                    end 
                end
            end
        end)
    end
    --printError(" base uiKey = " .. tostring(self.uiKey))
end




-- 需手动调用 Delete()
function IdolLive3D_UIBasicNode:__delete()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
end



----------------------------------------------------------


---@param isShow_ boolean 
function IdolLive3D_UIBasicNode:SetShow( isShow_ )
    self.isShow = (isShow_==true and self.isCustomShow==true)
    --printError("== set show " .. tostring(self.isShow) .. "; uiKey = " .. tostring(self.uiKey) )
    if type(self.baseSetShowFunc) == "function" then 
        self.baseSetShowFunc( self.isShow )
    end 
end



---@param isGray_ boolean @ 允许重复设置
function IdolLive3D_UIBasicNode:SetGray( isGray_ )
    self.isGray = (isGray_ == true or self.isCustomGray == true )
    --printError("== set gray " .. tostring(self.isGray) .. "; uiKey = " .. tostring(self.uiKey) )
    if type(self.baseSetGrayFunc) == "function" then 
        self.baseSetGrayFunc( self.isGray )
    end 
end



return IdolLive3D_UIBasicNode
